//! The artifact store: opaque generated bytes behind authorized URIs.
//!
//! Screenshots, recordings and other generated outputs are kept here, never in
//! the project. A public result names an artifact only by its opaque
//! `godot-mcp://artifacts/<hex>` URI and its [`ArtifactContract`]: media type,
//! length, SHA-256, owner and expiry. No storage location is representable in
//! anything this module hands out.
//!
//! The store is shared by every handler and transport, so it is interior
//! mutable. Registration is atomic and verified: the bytes must have exactly
//! the contract's length and SHA-256, the total-bytes budget must admit them,
//! and, for a durable store, the bytes and the contract are fsynced under the
//! server's private state directory before the artifact becomes readable.
//! A durable store reloads what it holds when the server starts, removing
//! every artifact whose retention has passed, and what it reloaded holds its
//! share of the total-bytes budget again. While the server runs, every
//! registration first removes what expired by then, so an expired artifact
//! gives its bytes and its budget back; an expired artifact reads as one that
//! never existed.

use std::collections::{BTreeMap, BTreeSet};
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};

use godot_mcp_domain::ErrorKind;
use godot_mcp_domain::contracts::{ArtifactContract, ByteRange, OutcomeError};
use sha2::{Digest, Sha256};

use crate::limits::{ArtifactReservation, LimitEnforcer};

fn outcome_error(kind: ErrorKind, message: impl Into<String>) -> OutcomeError {
    OutcomeError::new(kind, message, false, BTreeMap::new())
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(PoisonError::into_inner)
}

fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    bytes
        .iter()
        .fold(String::with_capacity(bytes.len() * 2), |mut text, byte| {
            let _ = write!(text, "{byte:02x}");
            text
        })
}

/// The SHA-256 of `bytes`, as an artifact contract spells it.
#[must_use]
pub(crate) fn sha256_hex(bytes: &[u8]) -> String {
    hex(&Sha256::digest(bytes))
}

enum Stored {
    Memory(Arc<Vec<u8>>),
    File(PathBuf),
}

struct Entry {
    contract: ArtifactContract,
    stored: Stored,
    /// Its share of the total-bytes budget, released when the entry is dropped.
    reservation: Option<ArtifactReservation>,
}

impl Entry {
    /// Remove the stored bytes and contract of a durable entry.
    fn remove_files(&self) {
        if let Stored::File(path) = &self.stored {
            let _ = std::fs::remove_file(path);
            let _ = std::fs::remove_file(path.with_extension("json"));
        }
    }
}

/// One authorized, retention-bounded set of artifacts.
pub struct ArtifactStore {
    directory: Option<PathBuf>,
    limits: Mutex<Option<Arc<LimitEnforcer>>>,
    entries: Mutex<BTreeMap<String, Entry>>,
    /// URIs whose registration is in flight; locked after `entries`.
    pending: Mutex<BTreeSet<String>>,
}

impl std::fmt::Debug for ArtifactStore {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ArtifactStore")
            .field("durable", &self.directory.is_some())
            .field("artifacts", &lock(&self.entries).len())
            .finish()
    }
}

impl Default for ArtifactStore {
    fn default() -> Self {
        Self::in_memory()
    }
}

/// A URI held for one registration in flight.
pub struct Reservation<'a> {
    store: &'a ArtifactStore,
    uri: String,
}

impl Drop for Reservation<'_> {
    fn drop(&mut self) {
        lock(&self.store.pending).remove(&self.uri);
    }
}

impl ArtifactStore {
    /// A store that keeps its artifacts in memory only.
    #[must_use]
    pub fn in_memory() -> Self {
        Self {
            directory: None,
            limits: Mutex::new(None),
            entries: Mutex::new(BTreeMap::new()),
            pending: Mutex::new(BTreeSet::new()),
        }
    }

    /// A durable store under the private `directory`, reloading every artifact
    /// still inside its retention at `now_unix_ms` and removing the rest.
    ///
    /// # Errors
    /// Returns a description when the directory cannot be created or read.
    pub fn open(directory: &Path, now_unix_ms: u64) -> Result<Self, String> {
        godot_mcp_domain::sysfs::open_private_state_dir(directory)
            .map_err(|error| error.to_string())?;
        let mut entries = BTreeMap::new();
        let listing = std::fs::read_dir(directory).map_err(|error| error.to_string())?;
        for item in listing.flatten() {
            let path = item.path();
            if path.extension().is_none_or(|extension| extension != "json") {
                continue;
            }
            let bytes_path = path.with_extension("bin");
            let contract = std::fs::read(&path)
                .ok()
                .and_then(|text| serde_json::from_slice::<ArtifactContract>(&text).ok());
            match contract {
                Some(contract)
                    if contract.expires_at_unix_ms() > now_unix_ms
                        && std::fs::metadata(&bytes_path).is_ok_and(|metadata| {
                            metadata.len() == contract.metadata().byte_length
                        })
                        && file_sha256(&bytes_path)
                            .is_some_and(|digest| digest == contract.metadata().sha256) =>
                {
                    entries.insert(
                        contract.resource_uri().as_str().to_owned(),
                        Entry {
                            contract,
                            stored: Stored::File(bytes_path),
                            reservation: None,
                        },
                    );
                }
                // Expired, unreadable, incomplete or changed since it was
                // registered: nothing may read it again.
                _ => {
                    let _ = std::fs::remove_file(&bytes_path);
                    let _ = std::fs::remove_file(&path);
                }
            }
        }
        Ok(Self {
            directory: Some(directory.to_path_buf()),
            limits: Mutex::new(None),
            entries: Mutex::new(entries),
            pending: Mutex::new(BTreeSet::new()),
        })
    }

    /// Account every artifact against `limits`' total-bytes budget: the ones
    /// a reopened store reloaded now, and every later registration. A reloaded
    /// artifact the budget cannot hold is removed, as if it had expired.
    pub fn attach_limits(&self, limits: Arc<LimitEnforcer>) {
        let evicted: Vec<Entry> = {
            let mut entries = lock(&self.entries);
            let unreserved: Vec<String> = entries
                .iter()
                .filter(|(_, entry)| entry.reservation.is_none())
                .map(|(uri, _)| uri.clone())
                .collect();
            let mut evicted = Vec::new();
            for uri in unreserved {
                let Some(entry) = entries.get_mut(&uri) else {
                    continue;
                };
                match Arc::clone(&limits).admit_artifact(entry.contract.metadata().byte_length) {
                    Ok(reservation) => entry.reservation = Some(reservation),
                    Err(_) => evicted.extend(entries.remove(&uri)),
                }
            }
            evicted
        };
        for entry in &evicted {
            entry.remove_files();
        }
        *lock(&self.limits) = Some(limits);
    }

    /// Register the bytes a server producer generated under `contract`,
    /// atomically, once they are verified against the contract's length and
    /// SHA-256.
    ///
    /// # Errors
    /// Returns `invalid_input` when the bytes do not have the contract's length
    /// and SHA-256, `conflict` when the URI is taken, the limit refusal when the
    /// budget is exhausted, and `internal` when a durable write fails.
    pub fn register(&self, contract: ArtifactContract, bytes: Vec<u8>) -> Result<(), OutcomeError> {
        if sha256_hex(&bytes) != contract.metadata().sha256 {
            return Err(outcome_error(
                ErrorKind::InvalidInput,
                "artifact bytes do not match the declared SHA-256",
            ));
        }
        self.register_declared(contract, bytes)
    }

    /// Register bytes whose digest the caller declares, checking only their
    /// length: the embedding API ([`crate::kernel::ServiceKernel::register_artifact`]),
    /// whose caller owns the contract it hands in.
    ///
    /// A registration happens at its artifact's creation time: everything that
    /// expired by then is removed first, so it no longer holds budget.
    ///
    /// # Errors
    /// As [`Self::register`], without the digest check.
    pub fn register_declared(
        &self,
        contract: ArtifactContract,
        bytes: Vec<u8>,
    ) -> Result<(), OutcomeError> {
        let length = u64::try_from(bytes.len()).unwrap_or(u64::MAX);
        if length != contract.metadata().byte_length {
            return Err(outcome_error(
                ErrorKind::InvalidInput,
                "artifact bytes do not match the declared length",
            ));
        }
        let uri = contract.resource_uri().as_str().to_owned();
        // Held until the entry is published, so no second registration of this
        // artifact writes its files meanwhile.
        let _held = self.reserve(&uri)?;
        self.purge_expired(contract.metadata().created_at_unix_ms);
        let limits = lock(&self.limits).clone();
        let reservation = limits
            .map(|limits| limits.admit_artifact(length))
            .transpose()
            .map_err(|rejection| rejection.to_outcome())?;
        let stored = match &self.directory {
            None => Stored::Memory(Arc::new(bytes)),
            Some(directory) => Stored::File(write_durably(directory, &contract, &bytes)?),
        };
        let mut entries = lock(&self.entries);
        if entries.contains_key(&uri) {
            return Err(outcome_error(
                ErrorKind::Conflict,
                "artifact is already registered",
            ));
        }
        entries.insert(
            uri,
            Entry {
                contract,
                stored,
                reservation,
            },
        );
        Ok(())
    }

    /// Hold `uri` for one registration until the guard drops.
    ///
    /// # Errors
    /// Returns `conflict` when the URI is registered or being registered.
    pub fn reserve(&self, uri: &str) -> Result<Reservation<'_>, OutcomeError> {
        let entries = lock(&self.entries);
        let mut pending = lock(&self.pending);
        if entries.contains_key(uri) || pending.contains(uri) {
            return Err(outcome_error(
                ErrorKind::Conflict,
                "artifact is already registered or being registered",
            ));
        }
        pending.insert(uri.to_owned());
        Ok(Reservation {
            store: self,
            uri: uri.to_owned(),
        })
    }

    /// Every registered contract, in URI order.
    #[must_use]
    pub fn contracts(&self) -> Vec<ArtifactContract> {
        lock(&self.entries)
            .values()
            .map(|entry| entry.contract.clone())
            .collect()
    }

    /// One artifact's contract.
    #[must_use]
    pub fn contract(&self, uri: &str) -> Option<ArtifactContract> {
        lock(&self.entries)
            .get(uri)
            .map(|entry| entry.contract.clone())
    }

    /// The bytes of `range` (already resolved against the contract) of `uri`.
    ///
    /// # Errors
    /// Returns `not_found` for an unknown artifact and `internal` when stored
    /// bytes cannot be read back.
    pub fn read_range(&self, uri: &str, range: &ByteRange) -> Result<Vec<u8>, OutcomeError> {
        let (stored, length) = {
            let entries = lock(&self.entries);
            let entry = entries
                .get(uri)
                .ok_or_else(|| outcome_error(ErrorKind::NotFound, "artifact was not found"))?;
            let stored = match &entry.stored {
                Stored::Memory(bytes) => Stored::Memory(Arc::clone(bytes)),
                Stored::File(path) => Stored::File(path.clone()),
            };
            (stored, entry.contract.metadata().byte_length)
        };
        if range.end_inclusive >= length || range.start > range.end_inclusive {
            return Err(outcome_error(
                ErrorKind::InvalidInput,
                "byte range exceeds the artifact length",
            ));
        }
        let start = usize::try_from(range.start)
            .map_err(|_| outcome_error(ErrorKind::InvalidInput, "artifact range is too large"))?;
        let count = usize::try_from(range.end_inclusive - range.start + 1)
            .map_err(|_| outcome_error(ErrorKind::InvalidInput, "artifact range is too large"))?;
        let inconsistent =
            || outcome_error(ErrorKind::Internal, "artifact storage is inconsistent");
        match stored {
            Stored::Memory(bytes) => bytes
                .get(start..start + count)
                .map(<[u8]>::to_vec)
                .ok_or_else(inconsistent),
            Stored::File(path) => {
                let mut file = std::fs::File::open(&path).map_err(|_| inconsistent())?;
                file.seek(SeekFrom::Start(range.start))
                    .map_err(|_| inconsistent())?;
                let mut bytes = vec![0_u8; count];
                file.read_exact(&mut bytes).map_err(|_| inconsistent())?;
                Ok(bytes)
            }
        }
    }

    /// Take back one artifact its producer could not complete: it stops
    /// resolving, its stored bytes are removed and its budget is released.
    pub(crate) fn withdraw(&self, uri: &str) {
        let removed = lock(&self.entries).remove(uri);
        if let Some(entry) = removed {
            entry.remove_files();
        }
    }

    /// Remove every artifact whose retention has passed at `now_unix_ms`.
    pub fn purge_expired(&self, now_unix_ms: u64) {
        let expired: Vec<Entry> = {
            let mut entries = lock(&self.entries);
            let uris: Vec<String> = entries
                .iter()
                .filter(|(_, entry)| entry.contract.expires_at_unix_ms() <= now_unix_ms)
                .map(|(uri, _)| uri.clone())
                .collect();
            uris.iter().filter_map(|uri| entries.remove(uri)).collect()
        };
        for entry in &expired {
            entry.remove_files();
        }
    }
}

/// Numbers each staging file of this process, so no two writes share one.
static STAGING: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// The SHA-256 of a file's bytes, read in bounded chunks.
pub(crate) fn file_sha256(path: &Path) -> Option<String> {
    let mut file = std::fs::File::open(path).ok()?;
    let mut hasher = Sha256::new();
    let mut buffer = vec![0_u8; 64 * 1024];
    loop {
        let read = file.read(&mut buffer).ok()?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Some(
        hasher
            .finalize()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect(),
    )
}

/// Write the bytes, then the contract, each through a private temporary file
/// that is fsynced and renamed into place, then fsync the directory. The
/// contract is written last: an artifact without its contract is never
/// reloaded.
fn write_durably(
    directory: &Path,
    contract: &ArtifactContract,
    bytes: &[u8],
) -> Result<PathBuf, OutcomeError> {
    let token = contract
        .artifact_id()
        .as_str()
        .strip_prefix("artifact_")
        .unwrap_or_default()
        .to_owned();
    let failed = |error: std::io::Error| {
        outcome_error(
            ErrorKind::Internal,
            format!("the artifact could not be stored: {error}"),
        )
    };
    let contract_bytes = serde_json::to_vec(contract)
        .map_err(|error| outcome_error(ErrorKind::Internal, error.to_string()))?;
    let bytes_path = directory.join(format!("{token}.bin"));
    for (target, content) in [
        (bytes_path.clone(), bytes),
        (
            directory.join(format!("{token}.json")),
            contract_bytes.as_slice(),
        ),
    ] {
        let staging = directory.join(format!(
            ".{}.{}-{}.staging",
            target
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("artifact"),
            std::process::id(),
            STAGING.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
        ));
        let mut options = std::fs::OpenOptions::new();
        options.write(true).create(true).truncate(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.mode(0o600);
        }
        let mut file = options.open(&staging).map_err(failed)?;
        file.write_all(content).map_err(failed)?;
        file.sync_all().map_err(failed)?;
        drop(file);
        std::fs::rename(&staging, &target).map_err(failed)?;
    }
    if let Ok(handle) = std::fs::File::open(directory) {
        let _ = handle.sync_all();
    }
    Ok(bytes_path)
}

#[cfg(test)]
mod tests {
    use super::*;
    use godot_mcp_domain::contracts::{
        ArtifactId, ArtifactKind, ArtifactMetadata, ArtifactResourceUri, ProjectIdentity,
        RangeSemantics,
    };
    use godot_mcp_domain::objid::{LeaseKey, StableObjectId};

    fn project() -> ProjectIdentity {
        ProjectIdentity::from_lease_key(
            LeaseKey {
                root: StableObjectId::Unix { dev: 1, ino: 2 },
                project_file: StableObjectId::Unix { dev: 1, ino: 3 },
            },
            1,
        )
    }

    fn contract(fill: char, bytes: &[u8], created: u64, expires: u64) -> ArtifactContract {
        let id = ArtifactId::parse(format!("artifact_{}", fill.to_string().repeat(64)))
            .expect("artifact id");
        let length = bytes.len() as u64;
        ArtifactContract::new(
            id.clone(),
            ArtifactResourceUri::for_artifact(&id),
            project(),
            None,
            ArtifactMetadata {
                kind: ArtifactKind::Screenshot,
                media_type: "image/png".to_owned(),
                byte_length: length,
                sha256: sha256_hex(bytes),
                created_at_unix_ms: created,
            },
            expires,
            RangeSemantics::new(length, length, true).expect("ranges"),
        )
        .expect("contract")
    }

    #[test]
    fn a_registration_must_carry_exactly_its_declared_bytes() {
        let store = ArtifactStore::in_memory();
        let declared = contract('a', b"hello", 1, 10);
        let refused = store
            .register(declared.clone(), b"hellO".to_vec())
            .expect_err("different bytes of the same length are refused");
        assert_eq!(refused.kind(), ErrorKind::InvalidInput);
        store
            .register(declared.clone(), b"hello".to_vec())
            .expect("the declared bytes register");
        let duplicate = store
            .register(declared.clone(), b"hello".to_vec())
            .expect_err("a URI registers once");
        assert_eq!(duplicate.kind(), ErrorKind::Conflict);
        let uri = declared.resource_uri().as_str();
        let range = ByteRange::new(1, 3).expect("range");
        assert_eq!(store.read_range(uri, &range).expect("read"), b"ell");
    }

    /// Bytes that changed on disk while the server was down are never served
    /// under the digest the contract recorded for them.
    #[test]
    fn a_reloaded_artifact_whose_bytes_changed_is_never_served() {
        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("artifacts");
        let kept = contract('d', b"original", 100, 10_000);
        {
            let store = ArtifactStore::open(&path, 100).expect("open");
            store
                .register(kept.clone(), b"original".to_vec())
                .expect("kept");
        }
        let token = "d".repeat(64);
        std::fs::write(path.join(format!("{token}.bin")), b"tampered").expect("same length");
        let reopened = ArtifactStore::open(&path, 500).expect("reopen");
        assert!(
            reopened.contracts().is_empty(),
            "an artifact whose bytes no longer match its digest is not reloaded"
        );
        assert!(!path.join(format!("{token}.bin")).exists());
    }

    /// A registration in flight holds its URI: a second registration of the
    /// same artifact is refused at once instead of writing the same files.
    #[test]
    fn an_artifact_being_registered_cannot_be_registered_again() {
        let directory = tempfile::tempdir().expect("tempdir");
        let store = ArtifactStore::open(&directory.path().join("artifacts"), 100).expect("open");
        let declared = contract('e', b"in flight", 100, 10_000);
        let held = store
            .reserve(declared.resource_uri().as_str())
            .expect("the first registration holds the URI");
        let refused = store
            .register(declared.clone(), b"in flight".to_vec())
            .expect_err("the URI is being registered");
        assert_eq!(refused.kind(), ErrorKind::Conflict);
        drop(held);
        store
            .register(declared, b"in flight".to_vec())
            .expect("once released, the URI registers");
    }

    #[test]
    fn a_durable_store_survives_a_restart_and_forgets_what_expired() {
        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("artifacts");
        let kept = contract('b', b"kept bytes", 100, 10_000);
        let expiring = contract('c', b"short", 100, 200);
        {
            let store = ArtifactStore::open(&path, 100).expect("open");
            store
                .register(kept.clone(), b"kept bytes".to_vec())
                .expect("kept");
            store
                .register(expiring.clone(), b"short".to_vec())
                .expect("expiring");
        }
        let reopened = ArtifactStore::open(&path, 500).expect("reopen");
        let uris: Vec<String> = reopened
            .contracts()
            .iter()
            .map(|contract| contract.resource_uri().as_str().to_owned())
            .collect();
        assert_eq!(uris, vec![kept.resource_uri().as_str().to_owned()]);
        let whole = ByteRange::new(0, 9).expect("range");
        assert_eq!(
            reopened
                .read_range(kept.resource_uri().as_str(), &whole)
                .expect("read back"),
            b"kept bytes"
        );
        let names: Vec<String> = std::fs::read_dir(&path)
            .expect("list")
            .map(|entry| {
                entry
                    .expect("entry")
                    .file_name()
                    .to_string_lossy()
                    .into_owned()
            })
            .collect();
        assert_eq!(
            names.len(),
            2,
            "only the kept artifact's two files remain: {names:?}"
        );
        reopened.purge_expired(20_000);
        assert!(reopened.contracts().is_empty());
        assert_eq!(std::fs::read_dir(&path).expect("list").count(), 0);
    }

    fn limits(total: u64) -> Arc<LimitEnforcer> {
        Arc::new(
            LimitEnforcer::new(crate::limits::LimitPolicy {
                max_artifact_total_bytes: total,
                ..crate::limits::LimitPolicy::default()
            })
            .expect("limits"),
        )
    }

    #[test]
    fn an_artifact_that_expired_gives_its_bytes_and_budget_back_to_the_next_one() {
        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("artifacts");
        let store = ArtifactStore::open(&path, 100).expect("open");
        let budget = limits(10);
        store.attach_limits(Arc::clone(&budget));
        let short = contract('d', b"12345678", 100, 200);
        store
            .register(short.clone(), b"12345678".to_vec())
            .expect("the first artifact fits");
        // Registered at 300, when the first one has expired: the budget it
        // held is free again, and nothing of it is left to read.
        let next = contract('e', b"abcdefgh", 300, 10_000);
        store
            .register(next.clone(), b"abcdefgh".to_vec())
            .expect("an expired artifact no longer holds budget");
        assert!(store.contract(short.resource_uri().as_str()).is_none());
        assert_eq!(budget.reserved_artifact_bytes(), 8);
        assert_eq!(
            std::fs::read_dir(&path).expect("list").count(),
            2,
            "only the live artifact's two files remain"
        );
    }

    #[test]
    fn a_reopened_store_counts_what_it_kept_against_the_budget() {
        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("artifacts");
        let kept = contract('f', b"0123456789", 100, 10_000);
        {
            let store = ArtifactStore::open(&path, 100).expect("open");
            store
                .register(kept.clone(), b"0123456789".to_vec())
                .expect("kept");
        }
        let reopened = ArtifactStore::open(&path, 500).expect("reopen");
        let budget = limits(15);
        reopened.attach_limits(Arc::clone(&budget));
        assert_eq!(
            budget.reserved_artifact_bytes(),
            10,
            "a reloaded artifact still holds its bytes of the budget"
        );
        let refused = reopened
            .register(
                contract('a', b"abcdefgh", 600, 10_000),
                b"abcdefgh".to_vec(),
            )
            .expect_err("the budget the reloaded artifact holds is not free");
        assert!(
            refused.message().contains("artifact_store_bytes"),
            "{refused:?}"
        );
    }
}
